using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text.Json;
using System.Threading.Channels;
using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
namespace SimplePZMapmaker.Web.Services;

public sealed record ExportJobStatus(string Id,string Kind,string Status,string SnapshotHash,string Revision,DateTimeOffset CreatedAtUtc,NativeExportProgress? Progress=null,string? Error=null,string? DownloadUrl=null,long Bytes=0);
public sealed class ExportJobStore:IDisposable
{
 sealed class Job(ExportJobStatus state){public ExportJobStatus State=state;public string? Section;public CancellationTokenSource Cancel=new();}
 readonly ConcurrentDictionary<string,Job> jobs=new();readonly object gate=new();readonly Channel<Job> queue;readonly CancellationTokenSource shutdown=new();readonly string directory;readonly Task[] workers;bool disposed;
 public NativeSectionCache Cache {get;}
 public ExportJobStore(string workspace,int running=2,int queued=8){if(running is <1 or >2||queued is <1 or >8)throw new ArgumentException("Native export capacity must be 1–2 running and 1–8 queued jobs.");directory=Path.Combine(workspace,"work","export-jobs");Directory.CreateDirectory(directory);Cache=new(Path.Combine(workspace,"work","native-section-cache"));Recover();queue=Channel.CreateBounded<Job>(new BoundedChannelOptions(queued){FullMode=BoundedChannelFullMode.Wait});workers=Enumerable.Range(0,running).Select(_=>Task.Run(Worker)).ToArray();}
 public ExportJobStatus StartMap(MapProject p){ProjectValidator.Validate(p);if(p.Spawns.Count==0)throw new ArgumentException("The standalone map needs a dry-land spawn point.");return Start("map",p,null);}
 public ExportJobStatus StartWorld(WorldProject world,string? memberId=null){WorldAssembler.Validate(world);if(memberId is not null&&!world.Maps.Any(m=>m.Id==memberId))throw new ArgumentException("Section not found.");return Start(memberId is null?"world":"section",world,memberId);}
 ExportJobStatus Start<T>(string kind,T source,string? section){lock(gate){ObjectDisposedException.ThrowIf(disposed,this);Prune();if(jobs.Values.Count(j=>j.State.Status is "queued" or "running")>=10)throw new ArgumentException("The export queue is full. Wait for a job or cancel one before adding another.");var id=Guid.NewGuid().ToString("N");var path=PathFor(id,"source");try{using(var output=File.Create(path)){using var bounded=new BoundedArchiveStream(output,128L*1024*1024,"The export snapshot exceeds 128 MB. Export selected sections separately.");JsonSerializer.Serialize(bounded,source,NativeMapExporter.JsonOptions);}using var input=File.OpenRead(path);var hash=Convert.ToHexString(SHA256.HashData(input)).ToLowerInvariant();var job=new Job(new(id,kind,"queued",hash,hash[..16],DateTimeOffset.UtcNow)){Section=section};jobs[id]=job;Save(job);if(!queue.Writer.TryWrite(job)){jobs.TryRemove(id,out _);DeleteOwned(id);throw new ArgumentException("The export queue is full. Wait for a job or cancel one before adding another.");}return job.State;}catch(Exception e){jobs.TryRemove(id,out _);DeleteOwned(id);if(e is IOException or UnauthorizedAccessException)throw new ArgumentException(Friendly(e));throw;}}}
 public ExportJobStatus Status(string id)=>Get(id).State;
 public ExportJobStatus[] List()=>jobs.Values.Select(j=>j.State).OrderByDescending(j=>j.CreatedAtUtc).ToArray();
 public ExportJobStatus Cancel(string id){lock(gate){var job=Get(id);if(job.State.Status is "queued" or "running"){job.Cancel.Cancel();if(job.State.Status=="queued"){Change(job,job.State with{Status="cancelled",Error="Export canceled. The project was preserved."});TryDelete(PathFor(id,"source"));}}return job.State;}}
 public IResult Download(string id){var job=Get(id);if(job.State.Status!="completed"||!File.Exists(PathFor(id,"zip")))throw new ArgumentException("The native archive is not ready or has expired. Queue a new export.");return Results.File(PathFor(id,"zip"),"application/zip",job.State.Kind=="world"?"SimplePZWorld.zip":job.State.Kind=="section"?"SimplePZSection.zip":"SimplePZMap.zip",enableRangeProcessing:true);}
 Job Get(string id)=>Safe(id)&&jobs.TryGetValue(id,out var job)?job:throw new ArgumentException("Export job not found.");
 async Task Worker(){try{await foreach(var job in queue.Reader.ReadAllAsync(shutdown.Token)){if(job.Cancel.IsCancellationRequested)continue;try{lock(gate){if(job.Cancel.IsCancellationRequested)continue;Change(job,job.State with{Status="running"});}using var linked=CancellationTokenSource.CreateLinkedTokenSource(job.Cancel.Token,shutdown.Token);linked.CancelAfter(TimeSpan.FromMinutes(30));var token=linked.Token;var context=new NativeExportContext(Cache,p=>{lock(gate){job.State=job.State with{Progress=p};if(p.Stage is "section-completed" or "completed")Save(job);}});using(var source=File.OpenRead(PathFor(job.State.Id,"source")))using(var file=File.Create(PathFor(job.State.Id,"partial"))){using var bounded=new BoundedArchiveStream(file,256L*1024*1024);if(job.State.Kind=="map")NativeMapExporter.ExportWithProgress(JsonSerializer.Deserialize<MapProject>(source,NativeMapExporter.JsonOptions)!,bounded,context,token);else{var world=JsonSerializer.Deserialize<WorldProject>(source,NativeMapExporter.JsonOptions)!;if(job.Section is {} section)NativeWorldExporter.ExportSectionWithProgress(world,section,bounded,context,token);else NativeWorldExporter.ExportWithProgress(world,bounded,context,token);}}
   token.ThrowIfCancellationRequested();lock(gate){token.ThrowIfCancellationRequested();var id=job.State.Id;File.Move(PathFor(id,"partial"),PathFor(id,"zip"),true);Change(job,job.State with{Status="completed",DownloadUrl=$"/api/export/jobs/{id}/download",Bytes=new FileInfo(PathFor(id,"zip")).Length});Prune();}
  }catch(OperationCanceledException){lock(gate)Fail(job,job.State with{Status=shutdown.IsCancellationRequested?"interrupted":job.Cancel.IsCancellationRequested?"cancelled":"failed",Error=shutdown.IsCancellationRequested?"Export was interrupted by application shutdown. Queue it again.":job.Cancel.IsCancellationRequested?"Export canceled. The project was preserved.":"Export exceeded 30 minutes. Export smaller sections separately."});}
  catch(Exception e){lock(gate)Fail(job,job.State with{Status="failed",Error=Friendly(e)});}
  finally{if(job.State.Status!="completed")TryDelete(PathFor(job.State.Id,"zip"));TryDelete(PathFor(job.State.Id,"partial"));TryDelete(PathFor(job.State.Id,"source"));}
 } }catch(OperationCanceledException){} }
 static string Friendly(Exception e)=>e switch{ArgumentException=>e.Message,IOException=>"The export could not write its workspace files. Check free disk space and retry.",UnauthorizedAccessException=>"The export workspace is not writable. Check folder permissions and retry.",OutOfMemoryException=>"The export needs more memory. Export selected sections separately.",_=>"The native export could not finish. Validate the project and retry with fewer sections."};
 void Fail(Job job,ExportJobStatus state){job.State=state;try{Save(job);}catch(Exception e) when(e is IOException or UnauthorizedAccessException){}}
 void Change(Job job,ExportJobStatus state){job.State=state;Save(job);}
 void Save(Job job){var target=PathFor(job.State.Id,"json");var temp=target+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(job.State,NativeMapExporter.JsonOptions));File.Move(temp,target,true);}
 string PathFor(string id,string suffix)=>Path.Combine(directory,id+"."+suffix);
 static bool Safe(string id)=>id.Length==32&&id.All(Uri.IsHexDigit);
 static void TryDelete(string path){try{if(File.Exists(path))File.Delete(path);}catch(IOException){}catch(UnauthorizedAccessException){}}
 void DeleteOwned(string id){foreach(var suffix in new[]{"source","partial","zip","json","json.tmp"})TryDelete(PathFor(id,suffix));}
 void Recover(){foreach(var path in Directory.EnumerateFiles(directory,"*.json")){var id=Path.GetFileNameWithoutExtension(path);if(!Safe(id))continue;try{if(new FileInfo(path).Length>32768)continue;var state=JsonSerializer.Deserialize<ExportJobStatus>(File.ReadAllText(path),NativeMapExporter.JsonOptions);if(state is null||state.Id!=id)continue;var job=new Job(state);if(state.Status is "queued" or "running")job.State=state with{Status="interrupted",Error="Application restarted before this export finished. Queue it again."};if(state.Status=="completed"&&!File.Exists(PathFor(id,"zip")))job.State=state with{Status="expired",DownloadUrl=null,Error="The archive has expired. Queue a new export."};jobs[id]=job;Save(job);}catch(Exception e) when(e is IOException or JsonException or UnauthorizedAccessException){}}foreach(var p in Directory.EnumerateFiles(directory)){var name=Path.GetFileName(p);var id=name.Split('.')[0];if(Safe(id)&&(name==id+".partial"||name==id+".source"||name==id+".json.tmp"))TryDelete(p);}Prune();}
 void Prune(){long bytes=0;var terminal=jobs.Values.Where(j=>j.State.Status is not ("queued" or "running")).OrderByDescending(j=>j.State.CreatedAtUtc).ToArray();for(var i=0;i<terminal.Length;i++){var job=terminal[i];bytes+=job.State.Bytes;if(i<24&&bytes<=1024L*1024*1024)continue;if(jobs.TryRemove(job.State.Id,out _)){DeleteOwned(job.State.Id);job.Cancel.Dispose();}}}
 public void Dispose(){lock(gate){if(disposed)return;disposed=true;shutdown.Cancel();queue.Writer.TryComplete();foreach(var job in jobs.Values)job.Cancel.Cancel();}try{Task.WaitAll(workers,TimeSpan.FromSeconds(10));}catch(AggregateException){} }
}
